INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'J-IC', '期初投入资本与分摊（统一估值引擎）', '已形成建议', '2026-06-30 股东权益 2,697.0 亿元，减去资产负债桥 C1—C10 的账面净额 1,964.9 亿元（现金储备、借款、租赁、经营所需现金、对外投资、基金外部出资人、少数股东），经营投入资本 732.1 亿元。公司不披露分部资产，按 2026 年收入×权重分到两块：手机×AIoT 生态 420.3 亿元（手机、AIoT 权重 1，互联网 0.2），汽车 311.8 亿元（权重 2）；AI 不分资本。之后各块资本占用率不变。粗略估计，待分部资产数据替换。', '投入资本是资产价值和 ROIC 的分母；收入增长按资本占用率占用新资本（汽车扩产的资本开支由此体现）。', '估值假设·期初投入资本、资本占用率', '公司披露分部资产，或汽车工厂投资计划有变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'J-VE', '按披露分部估值：生态一块、汽车一块（统一估值引擎）', '已形成建议', '公司披露两个分部：手机×AIoT、智能电动汽车及 AI 等创新业务。手机、AIoT、互联网共用用户、渠道和团队（互联网收入来自手机用户），营业费用无法真实拆分，所以生态按一块业务估值：三条收入线各自的销售成本按披露的分品类毛利率，营业费用作为生态共用的一条成本线。逐年收入、毛利率、费用率取 seed.py 里各情景的路径；所得税率 17%；汽车不再用 2030 年退出倍数和单独的 11% 折现率，改为逐年预测到 2035 年。', '生态经营利润＝三条收入线−三条销售成本−营业费用。', '估值假设·生态收入线与成本线、税率、汽车终值', '分部披露口径变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
